examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    MonarchInlineNotice(
        message = {{notices.0.message}},
        tone = {{notices.0.tone|tone}},
    )
    MonarchInlineNotice(
        message = {{notices.1.message}},
        tone = {{notices.1.tone|tone}},
    )
    MonarchInlineNotice(
        message = {{notices.2.message}},
        tone = {{notices.2.tone|tone}},
        title = {{notices.2.title}},
    )
    MonarchInlineNotice(
        message = {{notices.3.message}},
        tone = {{notices.3.tone|tone}},
        announcement = if ({{notices.3.live}}) MonarchBannerAnnouncement.Assertive else MonarchBannerAnnouncement.None,
        action = {
            MonarchButton(
                text = {{notices.3.action}},
                onClick = {},
                variant = MonarchButtonVariant.Secondary,
                size = MonarchButtonSize.Sm,
            )
        },
    )
    MonarchInlineNotice(
        message = {{notices.4.message}},
        tone = {{notices.4.tone|tone}},
        onDismiss = {},
    )
}

examples.code:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    MonarchInlineNotice(
        message = "Members sync from Rook ID every 15 minutes.",
        tone = MonarchTone.Info,
    )
    MonarchInlineNotice(
        message = "Connected to the shared inbox.",
        tone = MonarchTone.Success,
    )
    MonarchInlineNotice(
        message = "Emails from this domain may land in spam.",
        tone = MonarchTone.Warning,
        title = "Unverified.",
    )
    MonarchInlineNotice(
        message = "Could not load comments.",
        tone = MonarchTone.Danger,
        announcement = if (true) MonarchBannerAnnouncement.Assertive else MonarchBannerAnnouncement.None,
        action = {
            MonarchButton(
                text = "Retry",
                onClick = {},
                variant = MonarchButtonVariant.Secondary,
                size = MonarchButtonSize.Sm,
            )
        },
    )
    MonarchInlineNotice(
        message = "Draft restored from this device.",
        tone = MonarchTone.Neutral,
        onDismiss = {},
    )
}

if (shown) {
    MonarchInlineNotice(
        message = "This address is also used for invoices.",
        variant = MonarchInlineNoticeVariant.Plain,
        onDismiss = { shown = false },
    )
}
